import networkx as nx
G = nx.Graph()
for i in range(30):
    for j in range(i+1, 30):
        if (i//5 == j//5) or (i//5 == (j+1)//5) or ((i+1)//5 == j//5):
            G.add_edge(i, j)
if nx.girth(G) >= 7 and nx.algorithms.coloring.greedy_color(G).max() + 1 <= 5 and len(G.edges) >= 42:
    print("SATISFIABLE")
    print(list(G.edges))
else:
    print("UNSATISFIABLE")
